import { randomBytes } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

/** Slugs are generated by us and also come back from the URL, so validate them. */
const SLUG_PATTERN = /^[A-Za-z0-9_-]{10,24}$/;

/**
 * Uploaded photos live outside the app directory on purpose: `npm run deploy`
 * rsyncs with --delete, which would wipe anything stored under /var/www/retpap.
 */
export function uploadDir(): string {
  const configured = process.env.UPLOAD_DIR?.trim();
  return configured && configured.length > 0 ? configured : path.join(process.cwd(), "data", "uploads");
}

export function mediaUrl(slug: string): string {
  return "/media/" + slug + ".jpg";
}

export async function savePhoto(bytes: Buffer): Promise<string> {
  const dir = uploadDir();
  await mkdir(dir, { recursive: true });

  const slug = randomBytes(9).toString("base64url");
  await writeFile(path.join(dir, slug + ".jpg"), bytes, { flag: "wx" });
  return slug;
}

export async function readPhoto(slug: string): Promise<Buffer | null> {
  if (!SLUG_PATTERN.test(slug)) return null;

  try {
    return await readFile(path.join(uploadDir(), slug + ".jpg"));
  } catch {
    return null;
  }
}
